"""Authoring source for the studio textbook catalog; run to regenerate JSON."""
import json
from pathlib import Path

chapters = {}

def add(studio, text):
    for line in text.strip().splitlines():
        fields = line.split('|')
        if len(fields) != 12:
            raise ValueError((studio, len(fields), line))
        slug, core, equation, symbols, derivation, example, assumptions, misconception, investigation, question, answer, extension = fields
        chapters[slug] = dict(studio=studio, core=core, equation=equation, symbols=symbols,
            derivation=derivation.split(' / '), example=example.split(' / '), assumptions=assumptions,
            misconception=misconception, investigation=investigation, question=question,
            answer=answer, extension=extension)

